message.content:
=Kullanıcı bir ürün hakkında bilgiler (marka adı, ürün hakkında bilgi ve fotoğraf) gönderdi ve bu ürünü reklam videosuna dönüştürmek için bize bir konsept ve bilgiler verdi.

Marka: {{ $('Form Bilgisi Topla').item.json.data['Markanızın ismi nedir?'] }}

Ürün hakkında bilgi: {{ $('Form Bilgisi Topla').item.json.data['Üründen kısaca bahsediniz.'] }}

Reklam konsepti: {{ $('Form Bilgisi Topla').item.json.data['Lütfen video konusunu (prompt) yazınız.'] }}

Ürün fotoğrafı hakkında bilgi: {{ $json['0'].content[0].text }}

Senin görevin ürün hakkında araştırma yapmak ve bu araştırmayı sunmak. Bu araştırma ürünün hedef kitlesini analiz etmeli. Böylece reklam senaristimiz senin verdiğin araştırmayı kullanarak daha kapsamlı bir reklam senaryosu üretecektir.

Bugünün tarihi: {{ $now }}

parameters.jsCode:
// Shots Builder — per item
const j = $json || {};

// --- 1) first_scene_img_prompt temizliği ---
const output = j.output ?? {};
const rawPrompt = String(output.first_scene_img_prompt ?? '');

// LLM'den gelen prompt'u JSON için güvenli ve okunabilir hale getir
const safePrompt = rawPrompt
  .replace(/"/g, "'")          // çift tırnakları tek tırnağa çevir
  .replace(/[\r\n\t]+/g, ' ')  // newline / tab -> boşluk
  .replace(/\s+/g, ' ')        // birden fazla boşluk -> tek boşluk
  .trim();

// --- 2) shots kaynağını bul ---
const candidates = [ output.shots, j.shots, j.kiePayload?.input?.shots ]
  .filter(a => Array.isArray(a) && a.length > 0);
const src = candidates[0] || [];

// --- 3) shots normalize et ---
const shots = src.map((s, index) => {
  // Scene metni
  const rawScene = s.Scene ?? s.scene ?? s.prompt ?? s.description ?? '';
  const Scene = String(rawScene)
    .replace(/[\r\n\t]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  // duration: sayı değilse veya 0'dan küçükse varsayılan 3 sn
  let duration = Number(s.duration ?? s.Duration ?? 3);
  if (!Number.isFinite(duration) || duration <= 0) {
    duration = 3;
  }

  return {
    index,
    Scene,
    duration,
  };
});

// --- 4) Sonucu döndür ---
return {
  json: {
    ...j,
    output: {
      ...output,
      // orijinali koru
      first_scene_img_prompt: rawPrompt,
      // temizlenmiş versiyonu ekle
      first_scene_img_prompt_safe: safePrompt,
    },
    // top-level alias
    first_scene_img_prompt_safe: safePrompt,
    shots,
  },
};

// Bu node'un INPUT'u: "Görseli Al" node'u (Nano Banana Pro sonucu)

// 0) Ortak text temizleyici
const cleanText = (value) =>
  String(value ?? '')
    .replace(/"/g, "'")          // çift tırnakları tek tırnağa çevir
    .replace(/[\r\n\t]+/g, ' ')  // newline / tab -> boşluk
    .replace(/\s+/g, ' ')        // birden fazla boşluk -> tek boşluk
    .trim();

// 1) Form'dan süre ve aspect_ratio'yu al
const formData = $items('Form Bilgisi Topla')[0]?.json?.data ?? {};

const totalSeconds = Number(formData['Videonun uzunluğunu seçiniz.']) || 15;
const aspectRatio = String(
  formData['Video yatay mı yoksa dikey mi olsun?'] || 'portrait'
)
  .toLowerCase()
  .trim();

// 2) Shots Builder çıktısından sahneleri al
let shotsFromBuilder = $node['Shots Builder'].json.shots;
if (!Array.isArray(shotsFromBuilder)) shotsFromBuilder = [];

const shots = shotsFromBuilder.map((s) => ({
  Scene: cleanText(s.Scene ?? s.scene ?? s.prompt ?? ''),
  duration: Number(s.duration ?? s.Duration ?? 1) || 1,
}));

// 3) "Görseli Al" node'undan ilk sahne görsel URL'ini çek
const g = items[0]?.json ?? {};
let rawResult =
  g.data?.resultJson ??
  g.data?.result_json ??
  g.resultJson ??
  g.result_json;

let resultObj = rawResult;

// resultJson genelde string, önce parse etmeyi dene
if (typeof rawResult === 'string') {
  try {
    resultObj = JSON.parse(rawResult);
  } catch (e) {
    // Çift encode ihtimali için ikinci kez parse denemesi
    try {
      resultObj = JSON.parse(JSON.parse(rawResult));
    } catch (e2) {}
  }
}

let firstImageUrl;

if (
  resultObj &&
  Array.isArray(resultObj.resultUrls) &&
  resultObj.resultUrls.length > 0
) {
  firstImageUrl = resultObj.resultUrls[0];
}

// Hâlâ yoksa, tüm JSON içinde bir URL yakalamaya çalış (failsafe)
if (!firstImageUrl) {
  const haystack = JSON.stringify(g);
  const match = haystack.match(/https?:\/\/[^\s"'\\]+/);
  if (match) firstImageUrl = match[0];
}

// 4) Kie AI Sora 2 Pro Storyboard için final payload'ı hazırla
const payload = {
  model: 'sora-2-pro-storyboard',
  input: {
    n_frames: String(totalSeconds),
    image_urls: firstImageUrl ? [firstImageUrl] : [],
    aspect_ratio: aspectRatio,
    shots,
  },
};

// 5) n8n çıktısı
return [
  {
    json: payload,
  },
];

// Çıktı: { url: "<mp4 linki>" }
return items.map(item => {
  const j = item.json;

  // 1) "resultJson" varsa onu al, yoksa diğer olası alanları dene
  let raw = j.resultJson ?? j.result_json ?? j.result ?? j.resultUrls ?? j.resultUrl;

  // 2) String ise JSON.parse; iki kez kaçışlıysa iki kez parse dene
  let obj = raw;
  if (typeof obj === 'string') {
    try { obj = JSON.parse(obj); } catch(e) {}
    if (typeof obj === 'string') {
      try { obj = JSON.parse(obj); } catch(e2) {}
    }
  }

  // 3) Beklenen schema
  let url = Array.isArray(obj?.resultUrls) ? obj.resultUrls[0] : undefined;
  if (!url && typeof obj?.resultUrl === 'string') url = obj.resultUrl;

  // 4) Hâlâ yoksa regex ile mp4 yakala (soldaki tüm JSON’dan)
  if (!url) {
    const haystack = typeof raw === 'string' ? raw : JSON.stringify(j);
    const m = haystack.match(/https?:\/\/[^\s"'\\]+?\.mp4\b/);
    url = m ? m[0] : undefined;
  }

  return { json: { url } };
});

// Tüm item'ları al
const items = $input.all();

for (const item of items) {
  // Formdaki orientation alanını yakala
  // Buradaki key'i kendi formundaki key'le birebir aynı yap:
  const rawOrientation =
    (item.json['Video yatay mı yoksa dikey mi olsun?'] || item.json.orientation || '')
      .toString()
      .toLowerCase()
      .trim();

  let aspect;

  if (rawOrientation === 'portrait' || rawOrientation === 'dikey' || rawOrientation === 'vertical') {
    aspect = '9:16';
  } else if (rawOrientation === 'landscape' || rawOrientation === 'yatay' || rawOrientation === 'horizontal') {
    aspect = '16:9';
  } else {
    // Ne geldiğini anlamazsa varsayılan ver (istersen değiştir)
    aspect = '9:16';
  }

  // Kie'ye göndereceğin field
  item.json.aspect_ratio = aspect;
}

return items;

